/bin/bash -c "python - <<'PY'
import numpy as np
from PIL import Image
im=np.asarray(Image.open('first_frame.png')).astype(np.float32)
# report grayscale/color masks centroids by rough ROI
for name,(x0,y0,x1,y1) in {'ball':(900,250,1600,800),'block':(3000,450,3450,1100),'clampL':(900,0,1550,450),'clampR':(2700,0,3500,500)}.items():
 a=im[y0:y1,x0:x1]
 r,g,b=a[...,0],a[...,1],a[...,2]
 if name=='ball': m=(r>g*1.25)&(r>b*1.5)&(r<160)&(g>15)
 elif name=='block': m=(r>100)&(r>g*1.8)&(g<100)&(b<70)
 elif name=='clampL': m=(b>70)&(b>r*1.2)
 else: m=(r>90)&(r>g*1.5)&(g>20)&(b<80)
 yy,xx=np.where(m)
 print(name, len(xx), (x0+xx.mean(),y0+yy.mean()) if len(xx) else None, (x0+xx.min(),y0+yy.min(),x0+xx.max(),y0+yy.max()) if len(xx) else None)
PY"
